package com.lightning.mod.client.meshcapture.env;

/**
 * 一条"可拨动开关"类环境事实的取值：某个外部实现（典型是另一套渲染管线）的开关，本次运行里能不能被读到并安全拨动。
 * <p>
 * 与 {@link Capability} 分开：能力型事实回答"顶点通道能不能录到"；本取值只回答"我们能不能在捕获窗口内临时改变
 * 另一套实现的行为、并在窗口结束时无损还原"。{@link #ABSENT} 不是错误——它表示"这个开关不在场"，捕获流程必须
 * 照常走，只是不做那次临时拨动；{@link #UNKNOWN} 表示读不出来，同样按不拨动处理。
 */
public enum TogglePresence {

    /** 开关在场、签名可用，可以在捕获窗口内临时候拨动。 */
    PRESENT,

    /** 开关不在场（类/字段缺失或签名不是静态 boolean）：不拨动。 */
    ABSENT,

    /** 读取过程抛错，无法判断：按不拨动处理（保守）。 */
    UNKNOWN
}
